cat > /workspace/test_debug.c << 'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "ucl.h"

int main(int argc, char **argv) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <input_file>\n", argv[0]);
        return 1;
    }

    FILE *f = fopen(argv[1], "rb");
    if (!f) {
        fprintf(stderr, "Cannot open %s\n", argv[1]);
        return 1;
    }
    fseek(f, 0, SEEK_END);
    long size = ftell(f);
    fseek(f, 0, SEEK_SET);

    char *data = malloc(size);
    if (!data) {
        fclose(f);
        return 1;
    }
    fread(data, 1, size, f);
    fclose(f);

    printf("size=%ld, data=[", size);
    for (int i = 0; i < size; i++) {
        printf("%02x ", (unsigned char)data[i]);
    }
    printf("]\n");

    struct ucl_parser *parser;
    parser = ucl_parser_new(0);

    printf("Calling ucl_parser_add_string with len=%ld\n", size);
    int ret = ucl_parser_add_string(parser, data, size);
    printf("ucl_parser_add_string returned %d\n", ret);

    const char *err = ucl_parser_get_error(parser);
    if (err != NULL) {
        printf("Parse error: %s\n", err);
    }

    ucl_parser_free(parser);
    free(data);
    return 0;
}
EOF
